a) $A= \left\{ x \in \mathbb{Z} \mid -3 \le x \le 3 \right\} $ 

b) $A= \left\{ x \in \mathbb{Z} \mid -6 < x \le 6 \right\} $
\loigiai{
a) Thực hiện phép tính số nguyên: $A= \left\{ x \in \mathbb{Z} \mid -3 \le x \le 3 \right\}$.\\
b) Thực hiện phép tính số nguyên: $A= \left\{ x \in \mathbb{Z} \mid -6 < x \le 6 \right\}$.
}\end{ex}

